-- ============================================================ business-rule triggers
-- Double-entry integrity: every journal entry must balance at commit.
create or replace function fin.assert_journal_balanced() returns trigger language plpgsql as $$
declare d numeric; c numeric; eid uuid := coalesce(new.entry_id, old.entry_id);
begin
  select coalesce(sum(debit), 0), coalesce(sum(credit), 0) into d, c from fin.journal_lines where entry_id = eid;
  if d <> c then raise exception 'journal entry % is unbalanced (debit %, credit %)', eid, d, c; end if;
  return null;
end $$;
create constraint trigger trg_journal_balanced after insert on fin.journal_lines
  deferrable initially deferred for each row execute function fin.assert_journal_balanced();

-- ---- Fee obligations: derived fields can only be written by the roll-up trigger
create or replace function fin.guard_obligation_derived() returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('campx.allow_derived', true), 'off') = 'on' then return new; end if;
  if new.paid_amount is distinct from old.paid_amount then
    raise exception 'paid_amount is derived from fin.payment_allocations and cannot be edited directly' using errcode = '42501';
  end if;
  if new.status is distinct from old.status
     and (new.status in ('PAID', 'PARTIALLY_PAID') or old.status = 'PAID') then
    raise exception 'status % cannot be set or cleared directly; post or reverse an allocation instead', new.status using errcode = '42501';
  end if;
  return new;
end $$;
create trigger trg_guard_derived before update on fin.fee_obligations for each row execute function fin.guard_obligation_derived();

-- ---- Allocation invariants (append-only ledger)
create or replace function fin.guard_allocation() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_pay fin.payments%rowtype; v_obl fin.fee_obligations%rowtype; v_orig fin.payment_allocations%rowtype; v_allocated numeric;
begin
  -- fixed lock order (payment, then obligation) so concurrent postings serialise instead of deadlocking
  select * into v_pay from fin.payments where id = new.payment_id and tenant_id = new.tenant_id for update;
  select * into v_obl from fin.fee_obligations where id = new.obligation_id and tenant_id = new.tenant_id for update;
  if v_pay.id is null or v_obl.id is null then raise exception 'payment or obligation not found in this tenant'; end if;
  if v_pay.student_id is distinct from v_obl.student_id then
    raise exception 'payment % and obligation % belong to different students', v_pay.payment_no, v_obl.obligation_no using errcode = '23514';
  end if;
  if new.reverses_allocation_id is null then
    if v_pay.status not in ('SUCCESS', 'PARTIALLY_REFUNDED') then
      raise exception 'payment % is % and cannot be allocated', v_pay.payment_no, v_pay.status using errcode = '23514';
    end if;
    if v_obl.status in ('CANCELLED', 'WAIVED') then
      raise exception 'obligation % is % and cannot receive payments', v_obl.obligation_no, v_obl.status using errcode = '23514';
    end if;
    select coalesce(sum(amount), 0) into v_allocated from fin.payment_allocations where payment_id = new.payment_id and tenant_id = new.tenant_id;
    if v_allocated + new.amount > v_pay.amount then
      raise exception 'over-allocation: payment % has % unallocated, requested %', v_pay.payment_no, v_pay.amount - v_allocated, new.amount using errcode = '23514';
    end if;
  else
    select * into v_orig from fin.payment_allocations where id = new.reverses_allocation_id and tenant_id = new.tenant_id;
    if v_orig.id is null or v_orig.payment_id <> new.payment_id or v_orig.obligation_id <> new.obligation_id
       or v_orig.obligation_item_id is distinct from new.obligation_item_id or new.amount <> -v_orig.amount or v_orig.reverses_allocation_id is not null then
      raise exception 'a reversal must exactly mirror an original (non-reversal) allocation' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;
create trigger trg_a_guard before insert on fin.payment_allocations for each row execute function fin.guard_allocation();

-- ---- Roll-up: recompute from the ledger AFTER taking the row lock (separate statements => fresh snapshot, no lost update)
create or replace function fin.roll_up_obligation() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_sum numeric;
begin
  perform 1 from fin.fee_obligations where id = new.obligation_id and tenant_id = new.tenant_id for update;
  select coalesce(sum(amount), 0) into v_sum from fin.payment_allocations where obligation_id = new.obligation_id and tenant_id = new.tenant_id;
  perform set_config('campx.allow_derived', 'on', true);
  update fin.fee_obligations o set paid_amount = v_sum,
         status = case when v_sum >= o.net_amount and o.net_amount > 0 then 'PAID'
                       when o.status = 'OVERDUE' then 'OVERDUE'
                       when v_sum > 0 then 'PARTIALLY_PAID'
                       when o.status in ('PAID', 'PARTIALLY_PAID') then 'OPEN'
                       else o.status end
   where o.id = new.obligation_id and o.tenant_id = new.tenant_id;
  perform set_config('campx.allow_derived', 'off', true);
  return null;
end $$;
create trigger trg_roll_up_obligation after insert on fin.payment_allocations for each row execute function fin.roll_up_obligation();

-- Budget line roll-up from the append-only commitment ledger.
create or replace function bud.roll_up_line() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update bud.budget_lines l set
    committed_amount = coalesce((select sum(case c.entry_type when 'RELEASE' then -c.amount else c.amount end)
                                 from bud.commitments c where c.budget_line_id = l.id and c.entry_type in ('RESERVATION','COMMITMENT','RELEASE')), 0),
    actual_amount    = coalesce((select sum(c.amount) from bud.commitments c where c.budget_line_id = l.id and c.entry_type = 'ACTUAL'), 0)
  where l.id = new.budget_line_id;
  return null;
end $$;
create trigger trg_roll_up_line after insert on bud.commitments for each row execute function bud.roll_up_line();

-- Only one ACTIVE approval per (definition, entity) at a time is enforced by app logic; hard guard for exams:
create or replace function exm.guard_results_publish() returns trigger language plpgsql as $$
begin
  if new.status = 'PUBLISHED' and old.status is distinct from 'PUBLISHED' and new.published_at is null then
    new.published_at := now();
  end if;
  return new;
end $$;
create trigger trg_results_publish before update on exm.results for each row execute function exm.guard_results_publish();

