-- ============================================================ timetable business rules
create or replace function acd.guard_timetable_entry() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_tt record; v_sec record; v_off record; v_room record;
begin
  select t.college_id, t.term_id, t.batch_id into v_tt
    from acd.timetable_versions tv join acd.timetables t on t.id = tv.timetable_id and t.tenant_id = tv.tenant_id
   where tv.id = new.timetable_version_id and tv.tenant_id = new.tenant_id;
  if new.section_id is not null then
    select s.offering_id, s.batch_id into v_sec from acd.course_sections s where s.id = new.section_id and s.tenant_id = new.tenant_id;
    select o.college_id, o.term_id, o.course_id into v_off from acd.course_offerings o where o.id = v_sec.offering_id and o.tenant_id = new.tenant_id;
    if v_off.term_id is distinct from v_tt.term_id then raise exception 'section belongs to a different term than this timetable' using errcode = '23514'; end if;
    if v_off.college_id is distinct from v_tt.college_id then raise exception 'section belongs to a different college than this timetable' using errcode = '23514'; end if;
    if v_tt.batch_id is not null and v_sec.batch_id is not null and v_tt.batch_id <> v_sec.batch_id then
      raise exception 'section belongs to a different batch than this timetable' using errcode = '23514';
    end if;
    if new.subject_id is not null
       and exists (select 1 from acd.subject_course_map m where m.course_id = v_off.course_id and m.tenant_id = new.tenant_id)
       and not exists (select 1 from acd.subject_course_map m where m.course_id = v_off.course_id and m.subject_id = new.subject_id and m.tenant_id = new.tenant_id) then
      raise exception 'subject is not part of the section''s course' using errcode = '23514';
    end if;
    if new.employee_id is not null
       and not exists (select 1 from acd.section_faculty f where f.section_id = new.section_id and f.employee_id = new.employee_id
                       and f.tenant_id = new.tenant_id and f.deleted_at is null) then
      raise exception 'employee is not assigned to teach this section' using errcode = '23514';
    end if;
  end if;
  if new.room_id is not null then
    select c.college_id into v_room from core.rooms r join core.campuses c on c.id = r.campus_id and c.tenant_id = r.tenant_id
     where r.id = new.room_id and r.tenant_id = new.tenant_id;
    if v_tt.college_id is distinct from v_room.college_id then raise exception 'room belongs to a different college' using errcode = '23514'; end if;
  end if;
  return new;
end $$;
create trigger trg_guard_tt_entry before insert or update on acd.timetable_entries for each row execute function acd.guard_timetable_entry();

-- double-booking: same faculty / room / section cannot overlap on the same day within one timetable version
alter table acd.timetable_entries add constraint ex_tte_employee exclude using gist (
  tenant_id with =, timetable_version_id with =, employee_id with =, day_of_week with =,
  int4range(extract(epoch from start_time)::int, extract(epoch from end_time)::int) with &&)
  where (employee_id is not null and deleted_at is null and entry_type <> 'BREAK');
alter table acd.timetable_entries add constraint ex_tte_room exclude using gist (
  tenant_id with =, timetable_version_id with =, room_id with =, day_of_week with =,
  int4range(extract(epoch from start_time)::int, extract(epoch from end_time)::int) with &&)
  where (room_id is not null and deleted_at is null and entry_type <> 'BREAK');
alter table acd.timetable_entries add constraint ex_tte_section exclude using gist (
  tenant_id with =, timetable_version_id with =, section_id with =, day_of_week with =,
  int4range(extract(epoch from start_time)::int, extract(epoch from end_time)::int) with &&)
  where (section_id is not null and deleted_at is null and entry_type <> 'BREAK');

create trigger trg_guard_delegation before insert or update on iam.delegations for each row execute function iam.guard_delegation();
